import { promises as fs } from 'node:fs';
for(const p of ['scripts/build.mjs','assets/atlas.css','admin/config.yml','content/timeline.json'])await fs.access(p).catch(()=>{throw new Error(`Eksik: ${p}. Önce V22 kurulmuş olmalı.`)});
const append=async(f,p,m)=>{let s=await fs.readFile(f,'utf8');if(!s.includes(m)){s+='\n'+await fs.readFile(p,'utf8');await fs.writeFile(f,s)}};
await append('scripts/build.mjs','v22-1-build-patch.txt','V22.1 Context Capsule');await append('assets/atlas.css','v22-1-css-patch.txt','V22.1 Context Capsule');
let cfg=await fs.readFile('admin/config.yml','utf8');if(!cfg.includes('name: "trigger"')){const n='              - {label: "Neden kırılma noktası?", name: "why_turning_point", widget: "text"}';const a=`${n}\n              - {label: "Tetikleyici", name: "trigger", widget: "text", required: false, hint: "Süreci başlatan karar, kriz veya baskı neydi?"}\n              - {label: "Yapısal değişim", name: "structural_change", widget: "text", required: false, hint: "Kurallar, aktör dengesi veya politika aracı nasıl değişti?"}\n              - {label: "Önce", name: "before_state", widget: "text", required: false}\n              - {label: "Sonra", name: "after_state", widget: "text", required: false}\n              - {label: "Bugüne kalan miras", name: "legacy", widget: "text", required: false}\n              - {label: "Olmasaydı?", name: "counterfactual", widget: "text", required: false, hint: "Bu olay gerçekleşmeseydi olası alternatif seyir ne olurdu?"}\n              - {label: "Ölçek", name: "scale", widget: "select", required: false, options: ["ULUSAL", "BÖLGESEL", "KÜRESEL"]}\n              - {label: "Mekanizma", name: "mechanism", widget: "select", required: false, options: ["HUKUK", "DİPLOMASİ", "GÜVENLİK", "TİCARET", "ENERJİ", "KURUMLAŞMA"]}\n              - {label: "Yön", name: "direction", widget: "select", required: false, options: ["GENİŞLEME", "DARALMA", "KIRILMA", "GERİ DÖNÜŞ", "BELİRSİZ"]}\n              - {label: "Etki şiddeti", name: "impact_level", widget: "select", required: false, options: ["DÜŞÜK", "ORTA", "YÜKSEK", "SİSTEMİK"]}\n              - label: "İzlenecek sinyaller"\n                name: "signals"\n                widget: "list"\n                required: false\n                max: 6\n                field: {label: "Sinyal", name: "signal", widget: "string"}\n              - label: "Açık araştırma soruları"\n                name: "open_questions"\n                widget: "list"\n                required: false\n                max: 5\n                field: {label: "Soru", name: "question", widget: "string"}`;if(!cfg.includes(n))throw new Error('Timeline alanları bulunamadı');cfg=cfg.replace(n,a);await fs.writeFile('admin/config.yml',cfg)}
console.log('V22.1 kuruldu: Context Capsule olay tasarımı ve akıllı bağlam alanları eklendi.');
